+              message: "Use a phone number format like (555) 123-4567 or +1 555 123 4567."
+            });
+          }
+
+          if (errors.length > 0) {
+            errors.forEach(({ input, message }) => showFieldError(input, message));
+            status.textContent = "Please correct the highlighted fields and try again.";
+            status.dataset.state = "error";
+            errors[0].input.focus();
+            return;
+          }
+
+          status.textContent = "Thanks. Your support request is ready to send.";
+          status.dataset.state = "success";
+          form.reset();
+        });
+      }
+
+      renderApp();
+      attachFormBehavior();
+    </script>
+  </body>
+</html>
