        transition: top 0.2s ease;
      }

      .skip-link:focus {
        top: 1rem;
      }

      .page-shell {
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 100vh;
        padding: 2rem 1rem;
      }

      .support-layout {
        display: grid;
        grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
        gap: 1.5rem;
        width: min(100%, 1080px);
      }

      .panel {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
      }

      .hero-panel,
      .form-panel {
        padding: 2rem;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.8rem;
        border-radius: 999px;
        background: rgba(59, 130, 246, 0.1);
        color: var(--accent-strong);
        font-size: 0.92rem;
        font-weight: 700;
      }

      h1 {
        margin: 1rem 0 0.75rem;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1.05;
      }

      .hero-copy,
      .intro-copy,
      .field-helper,
      .required-note,
      .field-error,
      .status-message {
        color: var(--muted);
        line-height: 1.6;
      }

      .hero-copy,
      .intro-copy {
        font-size: 1rem;
        margin: 0;
      }

      .hero-points {
        display: grid;
        gap: 1rem;
        margin: 2rem 0 0;
        padding: 0;
        list-style: none;
      }

      .hero-points li {
        display: flex;
        gap: 0.9rem;
        align-items: flex-start;
        padding: 1rem;
        border-radius: 1rem;
        background: #f8fbff;
        border: 1px solid #e3ebf8;
      }

      .point-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 2.25rem;
        height: 2.25rem;
        border-radius: 999px;
        background: var(--accent);
        color: #fff;
        font-weight: 700;
        flex-shrink: 0;
      }

      .point-title {
        margin: 0;
        font-size: 1rem;
      }

      .point-copy {
        margin: 0.25rem 0 0;
        color: var(--muted);
      }

      .form-panel h2 {
        margin: 0;
        font-size: 1.5rem;
      }

      .intro-copy {
        margin-top: 0.75rem;
      }

      .required-note {
        margin: 1rem 0 0;
        font-size: 0.95rem;
      }

      form {
        margin-top: 1.5rem;
      }

      .form-field {
        margin-bottom: 1.25rem;
      }

      label {
        display: inline-block;
        margin-bottom: 0.45rem;
        font-weight: 700;
      }

      .required-indicator {
        color: var(--danger);
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        padding: 0.9rem 1rem;
        border: 1px solid #b7c5db;
        border-radius: 0.95rem;
        background: #fff;
        color: var(--text);
        font: inherit;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      input::placeholder {
        color: #6b7891;
      }

      input:hover {
        border-color: #8fa6c8;
      }

      input:focus {
        outline: 3px solid transparent;
        border-color: var(--accent-strong);
        box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.22);
      }

      .field-helper,
      .field-error,
      .status-message {
        margin: 0.45rem 0 0;
        font-size: 0.95rem;
      }

      .field-error {
        color: var(--danger);
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.14);
      }

      .actions {
        margin-top: 1.5rem;
      }

      .submit-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 3.25rem;
        min-width: 10rem;
        padding: 0.9rem 1.4rem;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 30px rgba(29, 78, 216, 0.24);
      }

      .submit-button:focus {
        outline: 3px solid transparent;
        box-shadow:
          0 0 0 4px rgba(59, 130, 246, 0.22),
          0 16px 30px rgba(29, 78, 216, 0.24);
      }

      .status-message {
        min-height: 1.5rem;
      }

      .status-message[data-state="success"] {
        color: #0f6b3f;
      }

      .status-message[data-state="error"] {
        color: var(--danger);
      }

      @media (max-width: 860px) {
        .support-layout {
          grid-template-columns: 1fr;
        }
      }

      @media (max-width: 480px) {
        .hero-panel,
        .form-panel {
          padding: 1.4rem;
        }
      }

      @media (forced-colors: active) {
        .panel,
        .hero-points li,
        input,
        .submit-button {
          border: 1px solid ButtonText;
          background: Canvas;
          color: CanvasText;
          box-shadow: none;
        }

        .submit-button,
        .eyebrow,
        .point-icon {
          background: ButtonFace;
          color: ButtonText;
        }

        .skip-link {
          background: CanvasText;
          color: Canvas;
        }

        input:focus,
        .submit-button:focus {
          outline: 2px solid Highlight;
          outline-offset: 2px;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const points = [
        {
          icon: "1",
          title: "Talk to support",
          copy: "Share a few details and our team will route your request to the right specialist."
        },
        {
          icon: "2",
          title: "Fast follow-up",
          copy: "Required details help us respond quickly without asking for basic information again."
        },
        {
          icon: "3",
          title: "Optional phone contact",
          copy: "Leave a number if you prefer a callback for urgent or hands-on support."
        }
      ];

      function HeroPanel() {
        return `
          <section class="panel hero-panel" aria-labelledby="support-heading">
            <span class="eyebrow">Support</span>
            <h1 id="support-heading">Contact our product support team</h1>
            <p class="hero-copy">
              Need help with setup, billing, or a product issue? Send us your details and we will follow up with the next best step.
            </p>
            <ul class="hero-points" aria-label="Support benefits">
              ${points
                .map(
                  (point) => `
                    <li>
                      <span class="point-icon" aria-hidden="true">${point.icon}</span>
                      <div>
                        <p class="point-title"><strong>${point.title}</strong></p>
                        <p class="point-copy">${point.copy}</p>
                      </div>
                    </li>
                  `
                )
                .join("")}
            </ul>
          </section>
        `;
      }

      function FormField({ id, label, type = "text", autocomplete = "", required = false, helperText = "" }) {
        const requiredText = required ? '<span class="required-indicator" aria-hidden="true"> *</span>' : "";
        const helperId = helperText ? `${id}-helper` : "";

        return `
          <div class="form-field">
            <label for="${id}">${label}${requiredText}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              ${required ? "required" : ""}
              aria-describedby="${helperId}"
            />
            ${helperText ? `<p class="field-helper" id="${helperId}">${helperText}</p>` : ""}
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="panel form-panel" aria-labelledby="form-heading">
            <h2 id="form-heading">Send a support request</h2>
            <p class="intro-copy">
              Fields marked with <span class="required-indicator" aria-hidden="true">*</span> are required.
            </p>
            <p class="required-note">We only use these details to contact you about your support request.</p>
            <form id="support-form" novalidate>
              ${FormField({
                id: "fullName",
                label: "Full name",
                autocomplete: "name",
                required: true
              })}
              ${FormField({
                id: "email",
                label: "Email address",
                type: "email",
                autocomplete: "email",
                required: true
              })}
              ${FormField({
                id: "phone",
                label: "Phone number",
                type: "tel",
                autocomplete: "tel",
                helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
              })}
              <div class="actions">
                <button class="submit-button" type="submit">Submit</button>
              </div>
              <p class="status-message" id="form-status" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      function SupportPage() {
        return `
          <div class="page-shell">
            <main id="main-content" class="support-layout">
              ${HeroPanel()}
              ${ContactForm()}
            </main>
          </div>
        `;
      }

      function renderApp() {
        document.getElementById("app").innerHTML = SupportPage();
      }

      function isValidEmail(value) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      }

      function clearErrors(form) {
        form.querySelectorAll(".field-error").forEach((node) => node.remove());
        form.querySelectorAll("input").forEach((input) => {
          input.removeAttribute("aria-invalid");
          const helperId = input.id === "phone" ? "phone-helper" : "";
          input.setAttribute("aria-describedby", helperId);
        });
      }

      function showFieldError(input, message) {
        input.setAttribute("aria-invalid", "true");
        const errorId = `${input.id}-error`;
        const helperId = input.id === "phone" ? "phone-helper" : "";
        input.setAttribute(
          "aria-describedby",
          [helperId, errorId].filter(Boolean).join(" ")
        );

        const error = document.createElement("p");
        error.className = "field-error";
        error.id = errorId;
        error.textContent = message;
        input.insertAdjacentElement("afterend", error);
      }

      function attachFormBehavior() {
        const form = document.getElementById("support-form");
        const status = document.getElementById("form-status");

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          clearErrors(form);
          status.textContent = "";
          status.dataset.state = "";

          const fullName = document.getElementById("fullName");
          const email = document.getElementById("email");
          const phone = document.getElementById("phone");

          const errors = [];

          if (!fullName.value.trim()) {
            errors.push({ input: fullName, message: "Enter your full name." });
          }

          if (!email.value.trim()) {
            errors.push({ input: email, message: "Enter your email address." });
          } else if (!isValidEmail(email.value.trim())) {
            errors.push({ input: email, message: "Enter a valid email address." });
          }

          if (phone.value.trim() && !/^[+\d\s().-]{7,}$/.test(phone.value.trim())) {
            errors.push({
              input: phone,
              message: "Use a phone number format like (555) 123-4567 or +1 555 123 4567."
            });
          }

          if (errors.length > 0) {
            errors.forEach(({ input, message }) => showFieldError(input, message));
            status.textContent = "Please correct the highlighted fields and try again.";
            status.dataset.state = "error";
            errors[0].input.focus();
            return;
          }

          status.textContent = "Thanks. Your support request is ready to send.";
          status.dataset.state = "success";
          form.reset();
        });
      }

      renderApp();
      attachFormBehavior();
    </script>
  </body>
</html>
