        }
      ];

      function HeroPanel() {
        return `
          <section class="panel hero-panel" aria-labelledby="support-heading">
            <span class="eyebrow">Support</span>
            <h1 id="support-heading">Contact our product support team</h1>
            <p class="hero-copy">
