       const points = [
         {
           icon: "1",
           title: "Talk to support",
           copy: "Share a few details and our team will route your request to the right specialist."
         },
         {
           icon: "2",
           title: "Fast follow-up",
           copy: "Required details help us respond quickly without asking for basic information again."
         },
         {
           icon: "3",
           title: "Optional phone contact",
           copy: "Leave a number if you prefer a callback for urgent or hands-on support."
         }
       ];

       function HeroPanel() {
         return `
           <section class="panel hero-panel" aria-labelledby="support-heading">
             <span class="eyebrow">Support</span>
             <h1 id="support-heading">Contact our product support team</h1>
             <p class="hero-copy">
               Need help with setup, billing, or a product issue? Send us your details and we will follow up with the next best step.
             </p>
             <ul class="hero-points" aria-label="Support benefits">
               ${points
                 .map(
                   (point) => `
                     <li>
                       <span class="point-icon" aria-hidden="true">${point.icon}</span>
                       <div>
                         <p class="point-title"><strong>${point.title}</strong></p>
                         <p class="point-copy">${point.copy}</p>
                       </div>
                     </li>
                   `
                 )
                 .join("")}
             </ul>
           </section>
         `;
       }

       function FormField({ id, label, type = "text", autocomplete = "", required = false, helperText = "" }) {
         const requiredText = required ? '<span class="required-indicator" aria-hidden="true"> *</span>' : "";
         const helperId = helperText ? `${id}-helper` : "";

         return `
           <div class="form-field">
             <label for="${id}">${label}${requiredText}</label>
             <input
               id="${id}"
               name="${id}"
               type="${type}"
               ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
               ${required ? "required" : ""}
               aria-describedby="${helperId}"
             />
             ${helperText ? `<p class="field-helper" id="${helperId}">${helperText}</p>` : ""}
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="panel form-panel" aria-labelledby="form-heading">
             <h2 id="form-heading">Send a support request</h2>
             <p class="intro-copy">
               Fields marked with <span class="required-indicator" aria-hidden="true">*</span> are required.
             </p>
             <p class="required-note">We only use these details to contact you about your support request.</p>
             <form id="support-form" novalidate>
               ${FormField({
                 id: "fullName",
                 label: "Full name",
                 autocomplete: "name",
                 required: true
               })}
               ${FormField({
                 id: "email",
                 label: "Email address",
                 type: "email",
                 autocomplete: "email",
                 required: true
               })}
               ${FormField({
                 id: "phone",
                 label: "Phone number",
                 type: "tel",
                 autocomplete: "tel",
                 helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
               })}
               <div class="actions">
                 <button class="submit-button" type="submit">Submit</button>
               </div>
               <p class="status-message" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function SupportPage() {
         return `
           <div class="page-shell">
             <main id="main-content" class="support-layout">
               ${HeroPanel()}
               ${ContactForm()}
             </main>
           </div>
         `;
       }

       function renderApp() {
         document.getElementById("app").innerHTML = SupportPage();
       }

       function isValidEmail(value) {
         return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
       }

       function clearErrors(form) {
         form.querySelectorAll(".field-error").forEach((node) => node.remove());
         form.querySelectorAll("input").forEach((input) => {
           input.removeAttribute("aria-invalid");
           const helperId = input.id === "phone" ? "phone-helper" : "";
           input.setAttribute("aria-describedby", helperId);
         });
       }

       function showFieldError(input, message) {
         input.setAttribute("aria-invalid", "true");
         const errorId = `${input.id}-error`;
         const helperId = input.id === "phone" ? "phone-helper" : "";
         input.setAttribute(
           "aria-describedby",
           [helperId, errorId].filter(Boolean).join(" ")
         );

         const error = document.createElement("p");
         error.className = "field-error";
         error.id = errorId;
         error.textContent = message;
         input.insertAdjacentElement("afterend", error);
       }

       function attachFormBehavior() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           clearErrors(form);
           status.textContent = "";
           status.dataset.state = "";

           const fullName = document.getElementById("fullName");
           const email = document.getElementById("email");
           const phone = document.getElementById("phone");

           const errors = [];

           if (!fullName.value.trim()) {
             errors.push({ input: fullName, message: "Enter your full name." });
           }

           if (!email.value.trim()) {
             errors.push({ input: email, message: "Enter your email address." });
           } else if (!isValidEmail(email.value.trim())) {
             errors.push({ input: email, message: "Enter a valid email address." });
           }

           if (phone.value.trim() && !/^[+\d\s().-]{7,}$/.test(phone.value.trim())) {
             errors.push({
               input: phone,
               message: "Use a phone number format like (555) 123-4567 or +1 555 123 4567."
             });
           }

           if (errors.length > 0) {
             errors.forEach(({ input, message }) => showFieldError(input, message));
             status.textContent = "Please correct the highlighted fields and try again.";
             status.dataset.state = "error";
             errors[0].input.focus();
             return;
           }

           status.textContent = "Thanks. Your support request is ready to send.";
           status.dataset.state = "success";
           form.reset();
